UPDATE posts
    SET up_votes = COALESCE(ups.count, 0),
        down_votes = COALESCE(downs.count, 0)
    FROM (
        SELECT post_id, COUNT(*) AS count
        FROM post_interactions
        WHERE direction = 'up'
        GROUP BY post_id
    ) AS ups
    FULL OUTER JOIN (
        SELECT post_id, COUNT(*) AS count
        FROM post_interactions
        WHERE direction = 'down'
        GROUP BY post_id
    ) AS downs ON ups.post_id = downs.post_id
    WHERE ups.post_id;

UPDATE comments
    SET up_votes = COALESCE(ups.count, 0),
        down_votes = COALESCE(downs.count, 0)
    FROM (
        SELECT comment_id, COUNT(*) AS count
        FROM comment_interactions
        WHERE direction = 'up'
        GROUP BY comment_id
    ) AS ups
    FULL OUTER JOIN (
        SELECT comment_id, COUNT(*) AS count
        FROM comment_interactions
        WHERE direction = 'down'
        GROUP BY comment_id
    ) AS downs ON ups.comment_id = downs.comment_id
    WHERE comments.id = ups.comment_id;

-- noinspection SqlWithoutWhere
UPDATE post_images
SET image_url = 'https://picsum.photos/seed/' || encode(gen_random_bytes(6), 'hex') || '/600/800';












